CREATE TABLE ibexa_content_type_group (id INT AUTO_INCREMENT NOT NULL, created INT DEFAULT 0 NOT NULL, creator_id INT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, modifier_id INT DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT NULL, is_system TINYINT(1) DEFAULT '0' NOT NULL, PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
